void BFS(Graph G, int v) {
    Queue Q;
    InitQueue(Q);
    visit(v);
    visited[v] = 1;
    EnQueue(Q, v);
    while (!IsEmpty(Q)) {
        DeQueue(Q, v);
        for (int w = FirstNeighbor(G, v); w >= 0; w = NextNeighbor(G, v, w)) {
            if (!visited[w]) {
                visit(w);
                visited[w] = 1;
                EnQueue(Q, w);
            }
        }
